/* Impact preview: the reference Deactivate doctor panel. One bordered panel,
   a small-caps header, hairline rows. Severity lives in the soft icon tile
   (a light wash of the tone, the glyph in the tone's ink, like the modal and
   toast tiles), never in a side bar or a filled row.

   Inside a glass modal the panel is a half-white pane so the glass still
   reads through it; the flat preset's white surface, square radii and
   neutral lines make it flat, square and neutral without a selector here. */

.panel {
  overflow: hidden;
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  background: color-mix(in srgb, var(--surface-solid) 64%, transparent);
  box-shadow: var(--shadow-input);
}

/* ── Header ─────────────────────────────────────────────────────────────── */

.header {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 14px 9px;
  background: color-mix(in srgb, var(--surface-sunken) 55%, transparent);
  border-bottom: 1px solid var(--line-soft);
}

/* With a danger statement the header takes the danger zone's flat tint. */
.headerDanger {
  background: var(--danger-fill);
}

.headerLine {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 18px;
}

/* A sentence-case heading, never a small uppercase label stacked over the
   statement. */
.title {
  font-family: var(--font-body);
  font-size: var(--text-small);
  font-weight: 700;
  line-height: 1.4;
  color: var(--ink-heading);
}

.loadingNote {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--text-caption);
  color: var(--ink-muted);
}

/* "This action cannot be undone": one compact line, no box of its own. */
.statement {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-size: var(--text-small);
  font-weight: 700;
  line-height: 1.4;
  color: var(--danger-ink);
}

.statement svg {
  flex-shrink: 0;
  margin-top: 2px;
}

/* Prose the rows don't carry (the legacy `consequences`), plain text. */
.lead {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 14px;
  font-size: var(--text-small);
  line-height: 1.55;
  color: var(--ink-body);
  text-wrap: pretty;
}

.lead + .rows,
.lead + .errorRow {
  border-top: 1px solid var(--line-soft);
}

/* ── Rows ───────────────────────────────────────────────────────────────── */

.rows {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* Severity channels, read by the tile, the affected chips and their dots. */
.destructive {
  --impact-color: var(--danger-solid);
  --impact-ink: var(--danger-ink);
  --impact-wash: color-mix(in srgb, var(--danger-solid) 12%, transparent);
}

.attention {
  --impact-color: var(--warning-solid);
  --impact-ink: var(--warning-ink);
  --impact-wash: var(--warning-fill);
}

.none {
  --impact-color: var(--success-solid);
  --impact-ink: var(--success-ink);
  --impact-wash: color-mix(in srgb, var(--success-solid) 11%, transparent);
}

.row,
.errorRow {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) auto;
  align-items: start;
  column-gap: 12px;
  padding: 12px 14px;
}

.errorRow {
  grid-template-columns: 32px minmax(0, 1fr);
}

.row + .row {
  border-top: 1px solid var(--line-soft);
}

.tile {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--r-sm);
  color: var(--impact-ink);
  background: var(--impact-wash);
  box-shadow:
    var(--shadow-specular),
    inset 0 0 0 1px color-mix(in srgb, var(--impact-ink) 14%, transparent);
}

.text {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  min-width: 0;
  /* Centres a one-line row on the 32 px tile. */
  padding-top: 6px;
}

.row:has(.rowDescription) .text,
.errorRow .text {
  padding-top: 0;
}

.rowTitle {
  font-size: var(--text-small);
  font-weight: 700;
  line-height: 1.45;
  color: var(--ink-heading);
  overflow-wrap: anywhere;
}

.rowDescription {
  font-size: var(--text-caption);
  line-height: 1.5;
  color: var(--ink-secondary);
  text-wrap: pretty;
}

/* Checked and nothing happens: a small green check at the row's end. */
.okBadge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  margin-top: 6px;
  border-radius: var(--r-circle, 50%);
  color: var(--success-ink);
  background: color-mix(in srgb, var(--success-solid) 12%, transparent);
}

.retry {
  margin-top: 8px;
}

/* ── Affected records ───────────────────────────────────────────────────── */

.affected {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.affectedItem {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  column-gap: 8px;
  row-gap: 2px;
  min-width: 0;
  padding: 5px 10px;
  border: 1px solid color-mix(in srgb, var(--impact-color) 14%, transparent);
  border-radius: var(--r-xs);
  background: color-mix(in srgb, var(--impact-color) 4%, transparent);
}

.dot {
  flex-shrink: 0;
  width: 6px;
  height: 6px;
  border-radius: var(--r-circle, 50%);
  background: var(--impact-color);
}

.affectedLabel {
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--ink-body);
}

.affectedDetail {
  font-size: var(--text-caption);
  line-height: 1.4;
  color: var(--ink-muted);
}

/* "Show 4 more": a text control, underlined on hover like a link. */
.more {
  margin-top: 6px;
  padding: 2px 4px;
  margin-left: -4px;
  border: 0;
  border-radius: var(--r-2xs);
  background: none;
  font: inherit;
  font-size: var(--text-caption);
  font-weight: 700;
  color: var(--ink-brand);
  cursor: pointer;
  transition: background-color 150ms var(--ease);
}

.more:disabled {
  color: var(--ink-disabled);
  cursor: default;
  text-decoration: none;
}

.more:hover:not(:disabled) {
  text-decoration: underline;
  text-underline-offset: 2px;
}

.more:active:not(:disabled) {
  background: var(--wash-active);
}

.more:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.skeletonText {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-top: 6px;
}

"use client";

import { useId, useState, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { Button } from "../Button/Button";
import { IconAlertCircle, IconAlertTriangle, IconCheck, IconCheckCircle, IconRefresh } from "../Icon/Icon";
import { Skeleton } from "../Skeleton/Skeleton";
import { Spinner } from "../Spinner/Spinner";
import styles from "./ImpactPreview.module.css";

/**
 * destructive = gone for good (access revoked, a record deleted).
 * attention = changes something someone should know about (reassigned, emailed).
 * none = checked and nothing happens here; says so, with a green check.
 */
export type ImpactSeverity = "destructive" | "attention" | "none";

export type ImpactAffected = {
  id: string;
  /** The thing affected, as the program shows it: "R.T.", "INV-0005". */
  label: ReactNode;
  /** One muted qualifier after it: "active 12 Aug", "keeps 2 other projects". */
  detail?: ReactNode;
};

export type ImpactItem = {
  id: string;
  severity: ImpactSeverity;
  /** 15 px glyph. Defaults to a triangle (destructive, attention) or a check (none). */
  icon?: ReactNode;
  /** One line, bold, stated as the outcome: "3 customers are reassigned". */
  title: ReactNode;
  /** One muted line under it: why, or what it takes to undo. */
  description?: ReactNode;
  /** Named records the row touches, listed under the explanation. */
  affected?: ImpactAffected[];
};

export type ImpactPreviewProps = {
  /** Default "Impact preview". */
  title?: ReactNode;
  /** Level of the small-caps heading. 3 inside a modal (the dialog title is the h2). */
  headingLevel?: 2 | 3 | 4;
  /**
   * A compact danger line under the heading, e.g. "This action cannot be
   * undone". TypeToConfirmModal passes its consequencesTitle here.
   */
  statement?: ReactNode;
  /**
   * One row per consequence. Omit for a panel of prose only (children); an
   * empty array renders the empty row ("Nothing else is affected").
   */
  items?: ImpactItem[];
  /** Plain text under the heading and above the rows: context the rows don't carry. */
  children?: ReactNode;
  /** The consequences are still being worked out on the server. */
  loading?: boolean;
  /** How many skeleton rows stand in while loading. Match the usual count. */
  loadingRows?: number;
  /** true for the default message, or the reason. Shown instead of the rows. */
  error?: ReactNode | boolean;
  /** Shows a Retry button in the error row. */
  onRetry?: () => void;
  /** Title of the row an empty items array renders. */
  emptyTitle?: ReactNode;
  /** Affected lists longer than this collapse behind "Show N more". Default 5. */
  affectedLimit?: number;
  className?: string;
};

const SEVERITY_LABEL: Record<ImpactSeverity, string> = {
  destructive: "Irreversible",
  attention: "Heads up",
  none: "No change",
};

function defaultIcon(severity: ImpactSeverity): ReactNode {
  return severity === "none" ? <IconCheckCircle size={15} /> : <IconAlertTriangle size={15} />;
}

/**
 * Impact preview: before an
 * irreversible action, one hairline row per consequence, so the person
 * confirming reads what will happen to whom, not a paragraph about it.
 * The tile's tone is the severity; a row with nothing to worry about says
 * so and carries a small green check, so "checked, nothing happens" never
 * reads the same as "not checked".
 */
export function ImpactPreview({
  title = "Impact preview",
  headingLevel = 3,
  statement,
  items,
  children,
  loading = false,
  loadingRows = 3,
  error,
  onRetry,
  emptyTitle = "Nothing else is affected",
  affectedLimit = 5,
  className,
}: ImpactPreviewProps) {
  const headingId = useId();
  const Heading = `h${headingLevel}` as const;
  const failed = Boolean(error) && !loading;

  return (
    <>
      <section data-slot="impact-preview"
        className={cx(styles.panel, className)}
        aria-labelledby={headingId}
        aria-busy={loading || undefined}
        data-surface="solid"
      >
        <header className={cx(styles.header, statement ? styles.headerDanger : null)}>
          <div className={styles.headerLine}>
            <Heading id={headingId} className={styles.title}>
              {title}
            </Heading>
            {loading ? (
              <span className={styles.loadingNote}>
                <Spinner size={13} />
                <span>Loading impact preview&hellip;</span>
              </span>
            ) : null}
          </div>
          {statement ? (
            <p className={styles.statement}>
              <IconAlertTriangle size={14} />
              <span>{statement}</span>
            </p>
          ) : null}
        </header>

        {children ? <div className={styles.lead}>{children}</div> : null}

        {loading ? (
          <ul className={styles.rows} aria-hidden="true">
            {Array.from({ length: Math.max(1, loadingRows) }, (_, i) => (
              <li key={i} className={styles.row}>
                <Skeleton width={32} height={32} radius="var(--r-sm)" />
                <span className={styles.skeletonText}>
                  <Skeleton variant="text" height={10} width={i % 2 ? "54%" : "68%"} />
                  <Skeleton variant="text" height={8} width={i % 2 ? "72%" : "46%"} />
                </span>
              </li>
            ))}
          </ul>
        ) : failed ? (
          <div className={styles.errorRow} role="alert">
            <span className={cx(styles.tile, styles.destructive)} aria-hidden="true">
              <IconAlertCircle size={15} />
            </span>
            <div className={styles.text}>
              <p className={styles.rowTitle}>Couldn&rsquo;t load the impact preview</p>
              <p className={styles.rowDescription}>
                {error === true ? "We couldn't work out what this changes. Try again before you confirm." : error}
              </p>
              {onRetry ? (
                <Button
                  variant="secondary"
                  size="sm"
                  className={styles.retry}
                  iconStart={<IconRefresh size={14} />}
                  onClick={onRetry}
                >
                  Try again
                </Button>
              ) : null}
            </div>
          </div>
        ) : items ? (
          <ul className={styles.rows}>
            {items.length === 0 ? (
              <ImpactRow item={{ id: "empty", severity: "none", title: emptyTitle }} limit={affectedLimit} />
            ) : (
              items.map((item) => <ImpactRow key={item.id} item={item} limit={affectedLimit} />)
            )}
          </ul>
        ) : null}
      </section>
      {/* The header note is visual; this is what a screen reader hears. Outside
        the section, because a live region inside aria-busy can be held back. */}
      <span className="sr-only" role="status" aria-live="polite">
        {loading ? "Loading impact preview." : ""}
      </span>
    </>
  );
}

function ImpactRow({ item, limit }: { item: ImpactItem; limit: number }) {
  const [expanded, setExpanded] = useState(false);
  const listId = useId();
  const { severity, icon, title, description, affected } = item;
  const list = affected ?? [];
  const hasAffected = list.length > 0;
  // "Show 1 more" costs a line to save a line: only collapse past limit + 1.
  const overflow = list.length > limit + 1;
  const shown = overflow && !expanded ? list.slice(0, limit) : list;
  const hidden = list.length - shown.length;

  return (
    <li className={cx(styles.row, styles[severity])}>
      <span className={cx(styles.tile, styles[severity])} aria-hidden="true">
        {icon ?? defaultIcon(severity)}
      </span>
      <div className={styles.text}>
        <p className={styles.rowTitle}>
          <span className="sr-only">{SEVERITY_LABEL[severity]}: </span>
          {title}
        </p>
        {description ? <p className={styles.rowDescription}>{description}</p> : null}
        {hasAffected ? (
          <>
            <ul id={listId} className={styles.affected}>
              {shown.map((a) => (
                <li key={a.id} className={styles.affectedItem}>
                  <span className={styles.dot} aria-hidden="true" />
                  <span className={styles.affectedLabel}>{a.label}</span>
                  {a.detail ? <span className={styles.affectedDetail}>{a.detail}</span> : null}
                </li>
              ))}
            </ul>
            {overflow ? (
              <button
                type="button"
                className={styles.more}
                aria-expanded={expanded}
                aria-controls={listId}
                onClick={() => setExpanded((v) => !v)}
              >
                {expanded ? "Show fewer" : `Show ${hidden} more`}
              </button>
            ) : null}
          </>
        ) : null}
      </div>
      {severity === "none" ? (
        <span className={styles.okBadge} aria-hidden="true">
          <IconCheck size={11} strokeWidth={3} />
        </span>
      ) : null}
    </li>
  );
}
